"""Evaluation metrics.

Requirement R9: AUC-ROC and AUC-PR.
Requirement R10: labels are consumed only *after* scores exist; every function
here takes the anomaly scores and the labels last, and no scoring code ever sees
the labels.
"""

from __future__ import annotations

import numpy as np
from sklearn.metrics import average_precision_score, precision_recall_curve
from sklearn.metrics import roc_auc_score as _sk_roc_auc


def roc_auc(scores, labels) -> float:
    """AUC-ROC (scores first: labels are used only for evaluation)."""
    return float(_sk_roc_auc(np.asarray(labels), np.asarray(scores)))


def average_precision(scores, labels) -> float:
    """AUC-PR as sklearn.average_precision_score (ADBench convention)."""
    return float(average_precision_score(np.asarray(labels), np.asarray(scores)))


def pr_curve_auc(scores, labels) -> float:
    """Secondary AUC-PR: trapezoidal area under the precision-recall curve."""
    prec, rec, _ = precision_recall_curve(np.asarray(labels), np.asarray(scores))
    order = np.argsort(rec)
    return float(np.trapz(prec[order], rec[order]))


def summarize(values) -> dict:
    """Mean / std (ddof=1) / min / max over repeated runs."""
    v = np.asarray(list(values), dtype=np.float64)
    return {
        "mean": float(v.mean()),
        "std": float(v.std(ddof=1)) if v.size > 1 else 0.0,
        "min": float(v.min()),
        "max": float(v.max()),
        "n": int(v.size),
        "values": [float(x) for x in v],
    }


def spearman(a, b) -> float:
    """Spearman rank correlation (used only for sanity checks)."""
    from scipy.stats import spearmanr

    return float(spearmanr(np.asarray(a), np.asarray(b)).statistic)

